begin;
insert into auth.users(id) values('11111111-1111-1111-1111-111111111111');
update daily_deck_private.auth_configuration set mode='preview';
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111111',true);
select public.daily_deck_complete_preview_onboarding(auth.uid(),true,true,false);
select test_support.expect_error($q$select public.daily_deck_sync_status('22222222-2222-2222-2222-222222222222',gen_random_uuid())$q$,array['42501'],'receipt status cannot be read for another user');
select test_support.assert_true((public.daily_deck_sync_status(auth.uid(),gen_random_uuid())->>'applied')='false','unknown request is never reported as saved');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'import',gen_random_uuid(),0,jsonb_build_object('localDay',current_date::text,'deck','{"version":1,"tasks":[{"owner_id":"22222222-2222-2222-2222-222222222222","id":"aaaaaaaa-0000-0000-0000-000000000001","kind":"today","title":"spoof","notes":"","weekdays":[],"created":"2026-01-01","archived":false}],"cards":[]}'::jsonb),'UTC')$q$,array['22023'],'import refuses owner overrides');
select test_support.assert_true((select count(*)=0 from public.daily_deck_items),'rejected import leaves no partial task rows');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'import',gen_random_uuid(),0,jsonb_build_object('localDay',current_date::text,'deck','{"version":1,"tasks":[{"id":"aaaaaaaa-0000-0000-0000-000000000001","kind":"today","title":"orphan","notes":"","minutes":null,"weekdays":[],"created":"2026-01-01","archived":false}],"cards":[]}'::jsonb),'UTC')$q$,array['23514'],'missing required one-time occurrence rolls back atomic import');
select test_support.assert_true((select count(*)=0 from public.daily_deck_items),'atomic relationship failure restores the empty account');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'import',gen_random_uuid(),0,jsonb_build_object('localDay',current_date::text,'deck','{"version":2,"tasks":[],"cards":[]}'::jsonb),'UTC')$q$,array['22023'],'unsupported import version rejected');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'read',gen_random_uuid(),0,'{"owner_id":"22222222-2222-2222-2222-222222222222"}','UTC')$q$,array['22023'],'read payload cannot change owner');
select test_support.expect_error('delete from public.daily_deck_occurrences',array['42501'],'historical occurrences have no direct DELETE grant');
select test_support.expect_error('update public.daily_deck_events set deck_order=0',array['42501'],'historical events have no direct UPDATE grant');
select test_support.expect_error('insert into public.daily_deck_schedule_versions default values',array['42501'],'schedule writes require trusted transaction');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'save',gen_random_uuid(),0,'{"localDay":"2000-01-01","task":{}}','UTC')$q$,array['40001'],'stale local date cannot backdate an ordinary action');
select test_support.expect_error($q$select public.daily_deck_sync(auth.uid(),'read',gen_random_uuid(),0,'{}','UTC;delete from auth.users')$q$,array['22023'],'timezone input is not executable SQL');
reset role;
set local role anon;
select test_support.expect_error('select public.daily_deck_sync_status(null,gen_random_uuid())',array['42501'],'anonymous receipt lookup denied');
reset role;
rollback;
